initJs:
function(container, apiUrl, tables) {
  // 初期化時の日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);
  const lastYear = new Date(today);
  lastYear.setFullYear(lastYear.getFullYear() - 1);

  // 日付フィールドの初期値設定
  container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = lastYear.toISOString().split('T')[0];
  container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリの読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryContainer = container.querySelector('#category-checkboxes');
    if (products) {
      const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
      categories.forEach(categoryId => {
        const label = document.createElement('label');
        label.style.cssText = 'display: flex; align-items: center; gap: 8px; color: var(--text);';
        label.innerHTML = `
          <input type="checkbox" class="category-checkbox" value="${categoryId}">
          <span>カテゴリ ${categoryId.substring(0, 8)}</span>
        `;
        categoryContainer.appendChild(label);
      });
    }
  }

  // 季節要因スライダーの値表示更新
  const seasonalSlider = container.querySelector('#seasonal-factor');
  const seasonalValue = container.querySelector('#seasonal-value');
  seasonalSlider.addEventListener('input', () => {
    seasonalValue.textContent = seasonalSlider.value;
  });

  // 全選択チェックボックス
  const selectAllCheckbox = container.querySelector('#select-all-categories');
  selectAllCheckbox.addEventListener('change', () => {
    const categoryCheckboxes = container.querySelectorAll('.category-checkbox');
    categoryCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllCheckbox.checked;
    });
  });

  // 天候データ取込ボタン
  container.querySelector('#btn-import-weather').addEventListener('click', async () => {
    const weatherStatus = container.querySelector('#weather-status');
    weatherStatus.textContent = '取込中...';
    weatherStatus.style.color = 'var(--primary)';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));
      weatherStatus.textContent = '取込完了';
      weatherStatus.style.color = '#22c55e';
    } catch (error) {
      weatherStatus.textContent = '取込失敗';
      weatherStatus.style.color = '#ff6a00';
    }
  });

  // イベントデータ取込ボタン
  container.querySelector('#btn-import-event').addEventListener('click', async () => {
    const eventStatus = container.querySelector('#event-status');
    eventStatus.textContent = '取込中...';
    eventStatus.style.color = 'var(--primary)';

    try {
      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));
      eventStatus.textContent = '取込完了';
      eventStatus.style.color = '#22c55e';
    } catch (error) {
      eventStatus.textContent = '取込失敗';
      eventStatus.style.color = '#ff6a00';
    }
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // 予測期間チェック
    const predictionStart = container.querySelector('#prediction-start-date').value;
    const predictionEnd = container.querySelector('#prediction-end-date').value;
    if (!predictionStart || !predictionEnd) {
      errors.push('予測期間の開始日と終了日を入力してください');
    } else {
      const startDate = new Date(predictionStart);
      const endDate = new Date(predictionEnd);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (startDate < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      const oneYearLater = new Date(startDate);
      oneYearLater.setFullYear(oneYearLater.getFullYear() + 1);
      if (endDate > oneYearLater) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    // 店舗選択チェック
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      errors.push('店舗を選択してください');
    }

    // 商品カテゴリチェック
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    // 予測モデルチェック
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    // 学習データ期間チェック
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間の開始日と終了日を入力してください');
    } else if (predictionStart && predictionEnd) {
      const learningDays = (new Date(learningEnd) - new Date(learningStart)) / (1000 * 60 * 60 * 24);
      const predictionDays = (new Date(predictionEnd) - new Date(predictionStart)) / (1000 * 60 * 60 * 24);
      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    container.querySelector('#success-message').classList.add('hidden');
  }

  // 成功表示関数
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    container.querySelector('#error-message').classList.add('hidden');
  }

  // 進捗表示関数
  function showProgress(percentage, message) {
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressMessage = container.querySelector('#progress-message');

    progressContainer.classList.remove('hidden');
    progressBar.style.width = percentage + '%';
    progressText.textContent = percentage + '%';
    progressMessage.textContent = message;
  }

  // 進捗非表示関数
  function hideProgress() {
    container.querySelector('#progress-container').classList.add('hidden');
  }

  // AI予測実行ボタン
  let isProcessing = false;
  container.querySelector('#btn-execute-prediction').addEventListener('click', async () => {
    if (isProcessing) return;

    // バリデーション
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    isProcessing = true;
    const executeBtn = container.querySelector('#btn-execute-prediction');
    executeBtn.disabled = true;
    executeBtn.textContent = '処理中...';

    // 他の操作を無効化
    const inputs = container.querySelectorAll('input, select, button');
    inputs.forEach(input => {
      if (input !== executeBtn) input.disabled = true;
    });

    container.querySelector('#error-message').classList.add('hidden');
    container.querySelector('#success-message').classList.add('hidden');

    try {
      // 進捗表示付きの模擬処理
      showProgress(0, 'データ収集を開始しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      showProgress(20, '売上実績データを分析中...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      showProgress(40, '天候データを分析中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      showProgress(60, 'イベントデータを分析中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      showProgress(80, 'AI予測モデルを実行中...');
      await new Promise(resolve => setTimeout(resolve, 2000));

      showProgress(100, '予測結果を生成中...');
      await new Promise(resolve => setTimeout(resolve, 500));

      // 予測結果データの保存
      const predictionData = {
        店舗ID: container.querySelector('#store-select').value,
        商品ID: 'dummy-product-id',
        予測対象日: container.querySelector('#prediction-start-date').value,
        予測数量: Math.floor(Math.random() * 100) + 50,
        予測精度: Math.floor(Math.random() * 20) + 80,
        推奨発注数量: Math.floor(Math.random() * 80) + 40,
        予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI需要予測処理により自動生成'
      };

      const saved = await window.aivicApi.save(9, predictionData); // 需要予測結果テーブル

      hideProgress();
      showSuccess('AI需要予測処理が正常に完了しました。予測結果が生成されました。');

    } catch (error) {
      hideProgress();
      showError('AI予測実行に失敗しました。システム管理者にお問い合わせください。');
    } finally {
      isProcessing = false;
      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';

      // 操作を再有効化
      inputs.forEach(input => input.disabled = false);
    }
  });

  // 初期データ読み込み
  loadStores();
  loadCategories();
}
